WITH sales_by_month AS (SELECT hd.hd_demo_sk, hd.hd_income_band_sk, i.i_category, date_trunc('month', date_add('day', ws.ws_sold_date_sk, DATE '1970-01-01')) AS sale_month, SUM(ws.ws_net_profit) AS month_profit FROM web_sales ws INNER JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk INNER JOIN item i ON ws.ws_item_sk = i.i_item_sk WHERE ws.ws_quantity > 5 GROUP BY hd.hd_demo_sk, hd.hd_income_band_sk, i.i_category, date_trunc('month', date_add('day', ws.ws_sold_date_sk, DATE '1970-01-01'))) SELECT hd_demo_sk, hd_income_band_sk, i_category, sale_month, month_profit, AVG(month_profit) OVER (PARTITION BY hd_income_band_sk ORDER BY sale_month ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS moving_avg_profit, CASE WHEN month_profit < 0 THEN 'Loss' WHEN month_profit BETWEEN 0 AND 500 THEN 'Low' WHEN month_profit BETWEEN 500 AND 5000 THEN 'Medium' ELSE 'High' END AS profit_category FROM sales_by_month ORDER BY hd_income_band_sk, sale_month DESC
